const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: 'F(x)=F₀(1−x/h), 0≤x≤h' },
      { kind: 'text', payload: 'x' },
      { kind: 'text', payload: 'F(x)' },
      { kind: 'text', payload: 'F₀' },
      { kind: 'text', payload: 'h' },
      { kind: 'text', payload: 'h/2' },
      { kind: 'text', payload: '0' },
      { kind: 'text', payload: '阴影面积' },
      { kind: 'text', payload: 'W/(F₀h) = 3/8 = 0.375' }
    ];
  },
  render: function (input, metrics) {
    var W = input.viewport.widthDu;
    var H = input.viewport.heightDu;
    var left = W * 0.16;
    var right = W * 0.88;
    var top = H * 0.20;
    var bottom = H * 0.78;
    var midX = (left + right) / 2;
    var midY = (top + bottom) / 2;
    var axisRight = right + Math.min(12, W * 0.02);
    var axisTop = top - Math.min(12, H * 0.03);
    var paths = [
      { id: 'shade', commands: [['M', left, bottom], ['L', left, top], ['L', midX, midY], ['L', midX, bottom], ['Z']] },
      { id: 'xaxis', commands: visualSdk.arrow(left, bottom, axisRight, bottom, {}) },
      { id: 'yaxis', commands: visualSdk.arrow(left, bottom, left, axisTop, {}) },
      { id: 'curve', commands: [['M', left, top], ['L', right, bottom]] },
      { id: 'midline', commands: [['M', midX, bottom], ['L', midX, midY]] }
    ];
    var children = [
      { type: 'path', pathId: 'shade', fill: '#7fb3d5AA', stroke: { width: 1 } },
      { type: 'path', pathId: 'xaxis', fill: '#26354a', stroke: { width: 2 } },
      { type: 'path', pathId: 'yaxis', fill: '#26354a', stroke: { width: 2 } },
      { type: 'path', pathId: 'curve', fill: '#26354a', stroke: { width: 2.5 } },
      { type: 'path', pathId: 'midline', fill: '#26354a', stroke: { width: 1.2 } },
      { type: 'label', contentId: metrics[0].contentId, anchor: { x: W * 0.5, y: H * 0.10 }, hAlign: 'center', vAlign: 'bottom', color: '#26354a' },
      { type: 'label', contentId: metrics[1].contentId, anchor: { x: axisRight, y: bottom - 14 }, hAlign: 'center', vAlign: 'bottom', color: '#26354a' },
      { type: 'label', contentId: metrics[2].contentId, anchor: { x: left, y: top - 18 }, hAlign: 'center', vAlign: 'bottom', color: '#26354a' },
      { type: 'label', contentId: metrics[3].contentId, anchor: { x: left - 10, y: top }, hAlign: 'right', vAlign: 'middle', color: '#26354a' },
      { type: 'label', contentId: metrics[4].contentId, anchor: { x: right, y: bottom + 20 }, hAlign: 'center', vAlign: 'top', color: '#26354a' },
      { type: 'label', contentId: metrics[5].contentId, anchor: { x: midX, y: bottom + 20 }, hAlign: 'center', vAlign: 'top', color: '#26354a' },
      { type: 'label', contentId: metrics[6].contentId, anchor: { x: left - 10, y: bottom + 16 }, hAlign: 'right', vAlign: 'top', color: '#26354a' },
      { type: 'label', contentId: metrics[7].contentId, anchor: { x: (left + midX) / 2, y: (midY + bottom) / 2 - 8 }, hAlign: 'center', vAlign: 'middle', color: '#26354a' },
      { type: 'label', contentId: metrics[8].contentId, anchor: { x: (left + midX) / 2, y: (midY + bottom) / 2 + 8 }, hAlign: 'center', vAlign: 'middle', color: '#26354a' }
    ];
    return {
      schemaVersion: 1,
      sceneId: 'f-x-linear-area',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: paths,
      root: { type: 'group', children: children }
    };
  }
};
